def hash_values(
    values: Iterable[Any],
    seed: Optional[str] = None,
    algorithm: Callable[[], hashlib._Hash] = _md5,
) -> str:
    h = _md5()
    if seed is not None:
        h.update(("%s\xff" % seed).encode("utf-8"))
    for value in values:
        hash_value(h, value)
    return h.hexdigest()
